const assert = require('node:assert/strict');

const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

const rows = [
  { id: 'b', tenant: 'a', createdAt: '2026-01-02T00:00:00Z', total: 2 },
  { id: 'a2', tenant: 'a', createdAt: '2026-01-01T00:00:00Z', total: 4 },
  { id: 'x', tenant: 'b', createdAt: '2026-01-01T00:00:00Z', total: 3 },
  { id: 'a1', tenant: 'a', createdAt: '2026-01-01T00:00:00Z', total: 1 },
  { id: 'a3', tenant: 'a', createdAt: '2026-01-03T00:00:00Z', total: 5 }
];
const repo = new OrderRepository(rows);
const handler = new OrderHandler(repo);

// Sorted ascending by createdAt then id, tenant filtered.
const p1 = handler.list({ tenant: 'a', limit: 2 });
assert.deepEqual(p1.items.map(x => x.id), ['a1', 'a2']);
assert.equal(p1.nextCursor, '2026-01-01T00:00:00Z|a2');

// Resume from cursor: strictly after, non-mutating input.
const p2 = handler.list({ tenant: 'a', limit: 2, cursor: p1.nextCursor });
assert.deepEqual(p2.items.map(x => x.id), ['b', 'a3']);
assert.equal(p2.nextCursor, null);

// Full walk yields all matching orders exactly once, in order.
const seen = [];
let cursor;
for (;;) {
  const page = handler.list({ tenant: 'a', limit: 2, ...(cursor ? { cursor } : {}) });
  seen.push(...page.items.map(x => x.id));
  if (page.nextCursor === null) break;
  cursor = page.nextCursor;
}
assert.deepEqual(seen, ['a1', 'a2', 'b', 'a3']);

// Cursor pair deleted: resumes strictly after that pair.
const volatileRepo = new OrderRepository(rows);
const vHandler = new OrderHandler(volatileRepo);
const first = vHandler.list({ tenant: 'a', limit: 1 });
assert.equal(first.nextCursor, '2026-01-01T00:00:00Z|a1');
rows.splice(rows.indexOf(rows.find(r => r.id === 'a1')), 1);
assert.deepEqual(vHandler.list({ tenant: 'a', limit: 2, cursor: '2026-01-01T00:00:00Z|a1' }).items.map(x => x.id), ['a2', 'b']);

// Cursor pair belonging to another tenant: filtering precedes pagination.
const tenantRepo = new OrderRepository(rows);
const tHandler = new OrderHandler(tenantRepo);
assert.deepEqual(tHandler.list({ tenant: 'a', limit: 10, cursor: '2026-01-01T00:00:00Z|x' }).items.map(x => x.id), ['a3']);

// Invalid requests.
assert.throws(() => handler.list({ tenant: '', limit: 1 }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 0 }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 101 }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1.5 }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: '2' }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor: '' }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor: 'a|b|c' }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor: 'onlyone' }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor: '|b' }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor: 'a|' }), /invalid request/);

// Limit larger than remaining: null nextCursor.
assert.deepEqual(handler.list({ tenant: 'a', limit: 100 }).items.map(x => x.id), ['a1', 'a2', 'a3']);
console.log('pagination checks passed');
