import { Order } from './types';
export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  private compare(a: Order, b: Order): number {
    return a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
  }
  list(tenant: string): Order[] {
    return this.rows.filter(row => row.tenant === tenant).sort((a, b) => this.compare(a, b));
  }
  listAfter(tenant: string, createdAt: string, id: string): Order[] {
    return this.list(tenant).filter(row => row.createdAt > createdAt || (row.createdAt === createdAt && row.id > id));
  }
}
